const menu=document.querySelector('.menu');const links=document.querySelector('.links');menu?.addEventListener('click',()=>{const open=links.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Schließen':'Menü';});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&links?.classList.contains('open'))menu.click()});document.querySelector('#project-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const body='Name: '+f.get('name')+'\nE-Mail: '+f.get('email')+'\nOrt: '+f.get('ort')+'\nThema: '+f.get('thema')+'\n\n'+f.get('message');window.location.href='mailto:info@tischlerei-gunia.de?subject='+encodeURIComponent('Projektanfrage – '+f.get('thema'))+'&body='+encodeURIComponent(body);document.querySelector('#form-status').textContent='Ihre E-Mail wird vorbereitet. Bitte senden Sie die Nachricht in Ihrem E-Mail-Programm ab. Alternativ erreichen Sie uns unter info@tischlerei-gunia.de.';});